<?php
declare(strict_types=1);
namespace App\Controllers; use App\Core\Request;use App\Core\View;use App\Core\Response;use App\Core\Session;use App\Middleware\PermissionMiddleware;use App\Repositories\UserRepository;
final class UserController {public function index(Request $r):void{PermissionMiddleware::require('users.view');$data=(new UserRepository())->all((string)$r->query('q',''),max(1,(int)$r->query('page',1)),10);$roles=(new UserRepository())->roles();View::render('users/index',compact('data','roles'));}public function store(Request $r):void{PermissionMiddleware::require('users.create');verify_csrf();$repo=new UserRepository();$id=$repo->create($r->all());$repo->setRole($id,(int)$r->input('role_id'));Session::flash('success','User created.');Response::redirect('/users');}public function update(Request $r,string $id):void{PermissionMiddleware::require('users.edit');verify_csrf();$repo=new UserRepository();$repo->update((int)$id,$r->all());$repo->setRole((int)$id,(int)$r->input('role_id'));Session::flash('success','User updated.');Response::redirect('/users');}}
